import * as THREE from 'three'
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js'
import { RectAreaLightUniformsLib } from 'three/addons/lights/RectAreaLightUniformsLib.js'
import {
  RoundedBoxGeometry, box, mesh, clamp, lerp, contactShadow, easeInOutCubic, easeOutCubic
} from './utils.js'
import {
  createWoodTexture, createPaperTexture, createVelvetTexture, createSealTexture,
  createBoxArtTexture, createBoxSideTexture, createCardboardBump, makeGradientSprite, FINISHES
} from './textures.js'
import { AccessorySet } from './accessories.js'

const BOX_W = 0.92
const BOX_H = 0.22
const BOX_D = 1.64
const LID_H = 0.105

class PeelSeal {
  constructor(side) {
    this.side = side
    this.group = new THREE.Group()
    this.group.name = `seal-${side > 0 ? 'right' : 'left'}`
    this.group.position.set(side * 0.29, BOX_H + LID_H + 0.003, BOX_D / 2 - 0.055)
    this.progress = 0
    this.removed = false
    const sealTex = createSealTexture()
    const sealMat = new THREE.MeshPhysicalMaterial({
      map: sealTex,
      metalness: 0.38,
      roughness: 0.22,
      clearcoat: 1,
      clearcoatRoughness: 0.08,
      iridescence: 0.7,
      iridescenceIOR: 1.3,
      iridescenceThicknessRange: [100, 500],
      side: THREE.DoubleSide,
      transparent: true,
      opacity: 0.97,
      envMapIntensity: 1.7
    })
    this.material = sealMat

    const frontGeo = new THREE.PlaneGeometry(0.14, 0.2, 16, 24)
    this.frontGeo = frontGeo
    this.frontBase = Float32Array.from(frontGeo.attributes.position.array)
    this.front = new THREE.Mesh(frontGeo, sealMat)
    this.front.position.set(0, -0.105, 0.036)
    this.front.userData.action = 'seal'
    this.front.userData.side = side
    this.front.castShadow = true
    this.group.add(this.front)

    const topGeo = new THREE.PlaneGeometry(0.14, 0.11, 12, 10)
    this.topBase = Float32Array.from(topGeo.attributes.position.array)
    this.top = new THREE.Mesh(topGeo, sealMat.clone())
    this.top.rotation.x = -Math.PI / 2
    this.top.position.set(0, 0.002, -0.05)
    this.top.userData.action = 'seal'
    this.top.userData.side = side
    this.group.add(this.top)

    const tabMat = new THREE.MeshPhysicalMaterial({
      color: 0xf4ead2, metalness: 0.25, roughness: 0.3, transparent: true, opacity: 0.95,
      clearcoat: 1, side: THREE.DoubleSide
    })
    this.tab = new THREE.Mesh(new THREE.PlaneGeometry(0.11, 0.045), tabMat)
    this.tab.position.set(side * 0.018, -0.213, 0.044)
    this.tab.rotation.z = side * 0.16
    this.tab.userData.action = 'seal'
    this.tab.userData.side = side
    this.group.add(this.tab)

    const label = new THREE.Mesh(
      new THREE.PlaneGeometry(0.09, 0.018),
      new THREE.MeshBasicMaterial({ color: 0x17171a, transparent: true, opacity: 0.62, side: THREE.DoubleSide })
    )
    label.position.set(0, -0.14, 0.047)
    this.group.add(label)
    this.label = label

    this.group.userData.action = 'seal'
    this.group.userData.side = side
  }

  setProgress(p) {
    this.progress = clamp(p)
    const e = easeInOutCubic(this.progress)
    this.group.rotation.x = -e * 1.12
    this.group.position.y = BOX_H + LID_H + 0.003 + e * 0.055
    this.group.position.z = BOX_D / 2 - 0.055 + e * 0.018
    this.group.position.x = this.side * (0.29 + e * 0.014)
    const pos = this.frontGeo.attributes.position
    const arr = pos.array
    const base = this.frontBase
    for (let i = 0; i < arr.length; i += 3) {
      const x = base[i]
      const y = base[i + 1]
      const t = clamp((0.1 - y) / 0.2)
      let z = base[i + 2]
      let ny = y
      let nx = x
      if (t < this.progress) {
        const local = (this.progress - t) / Math.max(0.001, this.progress)
        const angle = local * 2.2
        z += Math.sin(angle) * 0.052
        ny += (1 - Math.cos(angle)) * 0.036
        nx += Math.sin(angle * 1.7) * 0.006 * Math.sign(this.side)
      }
      arr[i] = nx
      arr[i + 1] = ny
      arr[i + 2] = z
    }
    pos.needsUpdate = true
    this.frontGeo.computeVertexNormals()

    const tpos = this.top.geometry.attributes.position
    const tarr = tpos.array
    for (let i = 0; i < tarr.length; i += 3) {
      const y = this.topBase[i + 1]
      const t = clamp((y + 0.055) / 0.11)
      tarr[i + 2] = this.topBase[i + 2] + Math.sin(t * Math.PI) * this.progress * 0.018
    }
    tpos.needsUpdate = true
    this.top.geometry.computeVertexNormals()
    this.top.material.opacity = 0.97 - this.progress * 0.1
    this.tab.rotation.x = -this.progress * 0.8
    this.tab.position.z = 0.044 + this.progress * 0.045
  }
}

class PhoneBox {
  constructor() {
    this.group = new THREE.Group()
    this.group.name = 'phone-box'
    this.config = { finish: 'graphite', model: 'AURA X1 PRO', short: 'X1 PRO', boxColor: '#0b0c10', accent: '#c7a97c' }
    this.seals = [new PeelSeal(1), new PeelSeal(-1)]
    this.accessories = new AccessorySet()
    this.lidOpen = 0
    this.build()
  }

  build() {
    const paperTex = createPaperTexture()
    const cardboard = createCardboardBump()
    this.paperMaterial = new THREE.MeshPhysicalMaterial({
      color: new THREE.Color(this.config.boxColor),
      roughness: 0.64,
      metalness: 0.04,
      bumpMap: cardboard,
      bumpScale: 0.0012,
      clearcoat: 0.14,
      clearcoatRoughness: 0.6,
      envMapIntensity: 0.65
    })
    const innerPaper = new THREE.MeshPhysicalMaterial({
      color: 0x191a1e, roughness: 0.72, metalness: 0.03, clearcoat: 0.06
    })
    const velvetTex = createVelvetTexture()
    this.velvetMaterial = new THREE.MeshPhysicalMaterial({
      map: velvetTex, color: 0xffffff, roughness: 0.95, metalness: 0,
      sheen: 1, sheenRoughness: 0.75, sheenColor: new THREE.Color('#5b5e68')
    })

    this.base = new THREE.Group()
    this.base.name = 'box-base'
    const bottom = box(BOX_W, 0.032, BOX_D, this.paperMaterial, [0, 0.016, 0], 0.012)
    this.base.add(bottom)
    const wallT = 0.038
    const sideL = box(wallT, BOX_H - 0.02, BOX_D, this.paperMaterial, [-BOX_W / 2 + wallT / 2, BOX_H / 2 + 0.008, 0], 0.01)
    const sideR = box(wallT, BOX_H - 0.02, BOX_D, this.paperMaterial, [BOX_W / 2 - wallT / 2, BOX_H / 2 + 0.008, 0], 0.01)
    const front = box(BOX_W - wallT * 2, BOX_H - 0.02, wallT, this.paperMaterial, [0, BOX_H / 2 + 0.008, BOX_D / 2 - wallT / 2], 0.008)
    const back = box(BOX_W - wallT * 2, BOX_H - 0.02, wallT, this.paperMaterial, [0, BOX_H / 2 + 0.008, -BOX_D / 2 + wallT / 2], 0.008)
    this.base.add(sideL, sideR, front, back)
    const lip = box(BOX_W - 0.02, 0.016, BOX_D - 0.02, innerPaper, [0, BOX_H - 0.004, 0], 0.01)
    this.base.add(lip)

    const tray = box(BOX_W - 0.075, 0.02, BOX_D - 0.085, this.velvetMaterial, [0, 0.045, 0], 0.018)
    this.base.add(tray)
    const phoneRecess = new THREE.Mesh(
      new THREE.PlaneGeometry(0.72, 1.56),
      new THREE.MeshPhysicalMaterial({ color: 0x09090b, roughness: 1, metalness: 0 })
    )
    phoneRecess.rotation.x = -Math.PI / 2
    phoneRecess.position.y = 0.057
    this.base.add(phoneRecess)
    this.phoneRecess = phoneRecess
    for (const x of [-0.39, 0.39]) {
      const rail = box(0.025, 0.025, 1.53, this.velvetMaterial, [x, 0.064, 0], 0.008)
      this.base.add(rail)
    }
    for (const z of [-0.76, 0.76]) {
      const rail = box(0.75, 0.025, 0.025, this.velvetMaterial, [0, 0.064, z], 0.008)
      this.base.add(rail)
    }

    const label = new THREE.Mesh(
      new THREE.PlaneGeometry(0.34, 0.06),
      new THREE.MeshBasicMaterial({ map: this.makeInnerLabel(), transparent: true, opacity: 0.62 })
    )
    label.rotation.x = -Math.PI / 2
    label.position.set(0, 0.059, -0.71)
    this.base.add(label)

    this.group.add(this.base)
    this.accessories.group.position.y = 0.055
    this.accessories.group.visible = false
    this.group.add(this.accessories.group)

    this.lid = new THREE.Group()
    this.lid.name = 'box-lid'
    this.lid.position.y = BOX_H + LID_H / 2
    this.lidHome = this.lid.position.clone()
    const lidMesh = new THREE.Mesh(
      new RoundedBoxGeometry(BOX_W + 0.03, LID_H, BOX_D + 0.03, 6, 0.018),
      this.paperMaterial
    )
    lidMesh.castShadow = true
    lidMesh.receiveShadow = true
    lidMesh.userData.action = 'lid'
    lidMesh.name = 'box-lid-hit'
    this.lid.add(lidMesh)
    this.lidMesh = lidMesh

    this.topPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(BOX_W - 0.034, BOX_D - 0.034),
      new THREE.MeshPhysicalMaterial({
        map: createBoxArtTexture(this.config),
        roughness: 0.5,
        metalness: 0.04,
        clearcoat: 0.3,
        clearcoatRoughness: 0.42,
        envMapIntensity: 0.85
      })
    )
    this.topPlane.rotation.x = -Math.PI / 2
    this.topPlane.position.y = LID_H / 2 + 0.002
    this.topPlane.receiveShadow = true
    this.topPlane.userData.action = 'lid'
    this.lid.add(this.topPlane)

    const sideTex = createBoxSideTexture(this.config)
    const sideMat = new THREE.MeshPhysicalMaterial({
      map: sideTex, roughness: 0.55, metalness: 0.04, clearcoat: 0.2, envMapIntensity: 0.7
    })
    this.sideMat = sideMat
    const frontLabel = new THREE.Mesh(new THREE.PlaneGeometry(BOX_W - 0.04, LID_H - 0.018), sideMat)
    frontLabel.position.set(0, 0, (BOX_D + 0.03) / 2 + 0.001)
    frontLabel.userData.action = 'lid'
    this.lid.add(frontLabel)
    const backLabel = new THREE.Mesh(new THREE.PlaneGeometry(BOX_W - 0.04, LID_H - 0.018), sideMat)
    backLabel.rotation.y = Math.PI
    backLabel.position.set(0, 0, -(BOX_D + 0.03) / 2 - 0.001)
    backLabel.userData.action = 'lid'
    this.lid.add(backLabel)

    const goldMat = new THREE.MeshPhysicalMaterial({ color: 0xc7a97c, metalness: 1, roughness: 0.25, envMapIntensity: 1.2 })
    const trimGeo = new THREE.BoxGeometry(0.006, 0.004, BOX_D + 0.025)
    for (const x of [-BOX_W / 2 - 0.012, BOX_W / 2 + 0.012]) {
      const trim = new THREE.Mesh(trimGeo, goldMat)
      trim.position.set(x, -LID_H / 2 + 0.01, 0)
      this.lid.add(trim)
    }
    const trimZGeo = new THREE.BoxGeometry(BOX_W + 0.025, 0.004, 0.006)
    for (const z of [-(BOX_D + 0.025) / 2, (BOX_D + 0.025) / 2]) {
      const trim = new THREE.Mesh(trimZGeo, goldMat)
      trim.position.set(0, -LID_H / 2 + 0.01, z)
      this.lid.add(trim)
    }

    this.group.add(this.lid)
    for (const seal of this.seals) this.group.add(seal.group)

    this.group.userData.box = this
    this.group.traverse(o => {
      if (o.isMesh) {
        o.castShadow = true
        o.receiveShadow = true
      }
    })
  }

  makeInnerLabel() {
    const canvas = document.createElement('canvas')
    canvas.width = 512
    canvas.height = 96
    const ctx = canvas.getContext('2d')
    ctx.clearRect(0, 0, 512, 96)
    ctx.fillStyle = '#d6c6ac'
    ctx.font = '500 22px Helvetica, Arial, sans-serif'
    ctx.textAlign = 'center'
    ctx.letterSpacing = '6px'
    ctx.fillText('AURA  ·  X1 PRO  ·  512GB', 256, 58)
    const tex = new THREE.CanvasTexture(canvas)
    tex.colorSpace = THREE.SRGBColorSpace
    return tex
  }

  setStyle(config = {}) {
    Object.assign(this.config, config)
    const oldTop = this.topPlane.material.map
    this.topPlane.material.map = createBoxArtTexture(this.config)
    this.topPlane.material.needsUpdate = true
    oldTop?.dispose()
    const oldSide = this.sideMat.map
    this.sideMat.map = createBoxSideTexture(this.config)
    this.sideMat.needsUpdate = true
    oldSide?.dispose()
    this.paperMaterial.color.set(this.config.boxColor || '#0b0c10')
    this.phoneRecess.material.color.set(this.config.boxColor || '#09090b')
  }

  setLidProgress(p) {
    this.lidOpen = clamp(p)
    const e = easeInOutCubic(this.lidOpen)
    this.lid.position.y = this.lidHome.y + e * 0.55
    this.lid.position.z = this.lidHome.z + e * 0.12
    this.lid.rotation.z = Math.sin(e * Math.PI) * 0.035
    this.lid.rotation.x = e * 0.11
  }

  revealAccessories() {
    this.accessories.group.visible = true
  }

  setAccessoriesVisible(v) {
    this.accessories.group.visible = v
  }

  setSealProgress(p, side = 1) {
    const seal = this.seals.find(s => s.side === side) || this.seals[0]
    seal.setProgress(p)
  }

  setBothSeals(p) {
    for (const s of this.seals) s.setProgress(p)
  }

  removeSeal(side) {
    const seal = this.seals.find(s => s.side === side)
    if (seal) seal.removed = true
  }

  reset() {
    this.lidOpen = 0
    this.lid.position.copy(this.lidHome)
    this.lid.rotation.set(0, 0, 0)
    this.setBothSeals(0)
    this.setAccessoriesVisible(false)
    for (const s of this.seals) s.removed = false
    this.accessories.group.visible = false
    for (const item of this.accessories.items) {
      item.position.copy(item.userData.home)
      item.rotation.copy(item.userData.homeRotation)
      item.rotation.y = item.userData.homeRotation.y
      item.scale.setScalar(item.userData.homeScale || item.scale.x)
    }
  }
}

export class World {
  constructor(renderer) {
    this.renderer = renderer
    this.scene = new THREE.Scene()
    this.scene.background = new THREE.Color('#090a0c')
    this.scene.fog = new THREE.FogExp2('#08090b', 0.035)
    this.camera = new THREE.PerspectiveCamera(36, 1, 0.05, 30)
    this.camera.position.set(0.52, 1.66, 2.72)
    this.cameraTarget = new THREE.Vector3(0.02, 0.24, 0.03)
    this.night = false
    this.clockTime = 0
    this.room = new THREE.Group()
    this.scene.add(this.room)
    this.props = new THREE.Group()
    this.scene.add(this.props)
    this.woodTextures = {
      walnut: createWoodTexture(7, 'walnut'),
      oak: createWoodTexture(12, 'oak'),
      ebony: createWoodTexture(21, 'ebony'),
      ash: createWoodTexture(33, 'ash')
    }
    this.createEnvironment()
    this.createRoom()
    this.createTable()
    this.createProps()
    this.createBox()
    this.createLights()
    this.createParticles()
    this.createReveal()
    this.updateCamera()
  }

  createEnvironment() {
    const pmrem = new THREE.PMREMGenerator(this.renderer)
    const env = pmrem.fromScene(new RoomEnvironment(), 0.04)
    this.scene.environment = env.texture
    this.scene.environmentIntensity = 0.75
    pmrem.dispose()
  }

  createRoom() {
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x2c2b2b, roughness: 0.92, metalness: 0.02 })
    this.wallMaterial = wallMat
    const wall = box(9, 5.6, 0.2, wallMat, [0, 1.5, -3.25], 0.02)
    wall.castShadow = false
    this.room.add(wall)
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x171513, roughness: 0.62, metalness: 0.04
    })
    const floor = box(9, 0.1, 7, floorMat, [0, -0.78, 0.5], 0.01)
    floor.receiveShadow = true
    this.room.add(floor)
    const ceiling = box(9, 0.1, 7, new THREE.MeshStandardMaterial({ color: 0x121315, roughness: 1 }), [0, 3.2, 0.5], 0.01)
    this.room.add(ceiling)

    const slatMat = new THREE.MeshStandardMaterial({ color: 0x3a2a20, roughness: 0.7, metalness: 0.03 })
    this.slatMaterial = slatMat
    for (let i = 0; i < 26; i++) {
      const x = -3.7 + i * 0.29
      if (x > -0.7 && x < 0.7) continue
      const slat = box(0.11, 2.6, 0.055, slatMat, [x, 1.18, -3.1], 0.004)
      slat.castShadow = false
      this.room.add(slat)
    }
    const ledMat = new THREE.MeshBasicMaterial({ color: 0xd9b27a })
    this.ledMaterial = ledMat
    for (const x of [-0.72, 0.72]) {
      const led = new THREE.Mesh(new THREE.BoxGeometry(0.012, 2.4, 0.012), ledMat)
      led.position.set(x, 1.2, -3.08)
      this.room.add(led)
    }
    const panelMat = new THREE.MeshPhysicalMaterial({
      color: 0x0f1115, roughness: 0.4, metalness: 0.6, clearcoat: 0.6
    })
    const panel = box(1.26, 2.48, 0.04, panelMat, [0, 1.25, -3.11], 0.01)
    this.room.add(panel)

    const shelfMat = new THREE.MeshStandardMaterial({ color: 0x191715, roughness: 0.55, metalness: 0.2 })
    const shelf = box(1.6, 0.045, 0.32, shelfMat, [2.35, 1.36, -3.03], 0.006)
    this.room.add(shelf)
    const shelf2 = shelf.clone()
    shelf2.position.y = 0.75
    this.room.add(shelf2)

    const bookColors = ['#5e5144', '#3d4b4d', '#7d6552', '#2f343a', '#8d7a5e']
    for (let i = 0; i < 8; i++) {
      const h = 0.18 + (i % 3) * 0.04
      const book = box(0.045, h, 0.2, new THREE.MeshStandardMaterial({ color: bookColors[i % bookColors.length], roughness: 0.8 }), [1.72 + i * 0.06, 1.36 + h / 2 + 0.022, -3.02], 0.004)
      this.room.add(book)
    }
    const vase = new THREE.Mesh(
      new THREE.CylinderGeometry(0.07, 0.1, 0.24, 32),
      new THREE.MeshPhysicalMaterial({ color: 0xd0c3ad, roughness: 0.5, metalness: 0.02, clearcoat: 0.4 })
    )
    vase.position.set(2.85, 1.48, -3.03)
    vase.castShadow = true
    this.room.add(vase)
    const branchMat = new THREE.MeshStandardMaterial({ color: 0x3f382c, roughness: 0.8 })
    for (let i = 0; i < 4; i++) {
      const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.006, 0.34 + i * 0.04, 8), branchMat)
      branch.position.set(2.85 + (i - 1.5) * 0.03, 1.78 + i * 0.03, -3.03)
      branch.rotation.z = (i - 1.5) * 0.17
      this.room.add(branch)
    }

    const windowMat = new THREE.MeshBasicMaterial({ color: 0xaec4cc, transparent: true, opacity: 0.16 })
    this.windowMaterial = windowMat
    const win = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 2.4), windowMat)
    win.position.set(-2.5, 1.55, -3.13)
    this.room.add(win)
    const winFrame = new THREE.MeshStandardMaterial({ color: 0x17181b, roughness: 0.5, metalness: 0.4 })
    for (const x of [-3.28, -1.72]) {
      const bar = box(0.045, 2.48, 0.06, winFrame, [x, 1.55, -3.11], 0.004)
      this.room.add(bar)
    }
    for (const y of [0.32, 2.78]) {
      const bar = box(1.6, 0.045, 0.06, winFrame, [-2.5, y, -3.11], 0.004)
      this.room.add(bar)
    }
    const mullion = box(0.035, 2.4, 0.05, winFrame, [-2.5, 1.55, -3.11], 0.003)
    this.room.add(mullion)
    this.windowPlane = win

    const artFrame = box(1.0, 1.2, 0.03, new THREE.MeshStandardMaterial({ color: 0x0d0e11, roughness: 0.4, metalness: 0.5 }), [-1.8, 1.72, -3.12], 0.004)
    this.room.add(artFrame)
    const art = new THREE.Mesh(
      new THREE.PlaneGeometry(0.88, 1.08),
      new THREE.MeshStandardMaterial({ color: 0x3c4b4d, roughness: 0.9 })
    )
    art.position.set(-1.8, 1.72, -3.1)
    this.room.add(art)
  }

  createTable() {
    const wood = this.woodTextures.walnut
    this.tableMaterial = new THREE.MeshPhysicalMaterial({
      map: wood.map,
      roughnessMap: wood.roughnessMap,
      bumpMap: wood.bumpMap,
      bumpScale: 0.004,
      roughness: 0.42,
      metalness: 0.02,
      clearcoat: 0.32,
      clearcoatRoughness: 0.24,
      envMapIntensity: 0.85
    })
    const top = new THREE.Mesh(new RoundedBoxGeometry(5.1, 0.11, 3.15, 6, 0.035), this.tableMaterial)
    top.position.set(0, -0.062, 0.18)
    top.receiveShadow = true
    top.castShadow = true
    this.props.add(top)
    this.tableTop = top
    const edge = box(5.14, 0.035, 3.18, new THREE.MeshPhysicalMaterial({
      color: 0x24160f, roughness: 0.5, metalness: 0.05, clearcoat: 0.3
    }), [0, -0.125, 0.18], 0.01)
    this.props.add(edge)
    const legMat = new THREE.MeshStandardMaterial({ color: 0x181615, roughness: 0.45, metalness: 0.45 })
    for (const [x, z] of [[-2.15, -0.95], [2.15, -0.95], [-2.15, 1.3], [2.15, 1.3]]) {
      const leg = box(0.11, 0.72, 0.11, legMat, [x, -0.46, z], 0.012)
      this.props.add(leg)
    }
    const tableShadow = contactShadow(3.2, 0.5, '#000000')
    tableShadow.position.set(0, 0.001, 0.18)
    tableShadow.rotation.x = -Math.PI / 2
    this.props.add(tableShadow)
  }

  createProps() {
    const clothMat = new THREE.MeshPhysicalMaterial({
      color: 0x777d7e, roughness: 0.94, metalness: 0, sheen: 1, sheenColor: new THREE.Color('#a8ada8'), sheenRoughness: 0.9
    })
    const cloth = new THREE.Group()
    const c1 = box(0.56, 0.018, 0.34, clothMat, [0, 0.01, 0], 0.02)
    const c2 = box(0.47, 0.014, 0.27, clothMat, [0.02, 0.025, 0.02], 0.02)
    c2.rotation.y = 0.12
    const c3 = box(0.28, 0.01, 0.19, clothMat, [0.05, 0.036, -0.02], 0.02)
    c3.rotation.y = -0.2
    cloth.add(c1, c2, c3)
    const stitch = new THREE.Mesh(
      new THREE.BoxGeometry(0.36, 0.001, 0.003),
      new THREE.MeshBasicMaterial({ color: 0x4e5252 })
    )
    stitch.position.set(0, 0.043, 0.07)
    cloth.add(stitch)
    const logo = new THREE.Mesh(
      new THREE.PlaneGeometry(0.1, 0.025),
      new THREE.MeshBasicMaterial({ map: this.makePropLogo('AURA'), transparent: true })
    )
    logo.rotation.x = -Math.PI / 2
    logo.position.set(0.12, 0.045, -0.02)
    cloth.add(logo)
    cloth.position.set(-1.25, 0, 0.58)
    cloth.rotation.y = -0.25
    this.props.add(cloth)
    const cs = contactShadow(0.72, 0.35)
    cs.position.set(-1.25, 0.001, 0.58)
    this.props.add(cs)

    const standMat = new THREE.MeshPhysicalMaterial({
      color: 0x9b9489, metalness: 0.95, roughness: 0.24, envMapIntensity: 1.4
    })
    const stand = new THREE.Group()
    const base = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.23, 0.025, 48), standMat)
    base.position.y = 0.012
    base.castShadow = true
    stand.add(base)
    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.03, 0.62, 24), standMat)
    stem.position.set(0, 0.32, -0.05)
    stem.rotation.x = 0.08
    stem.castShadow = true
    stand.add(stem)
    const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.27, 20), standMat)
    arm.position.set(0, 0.62, 0.02)
    arm.rotation.x = 0.75
    stand.add(arm)
    const cradle = box(0.18, 0.055, 0.08, standMat, [0, 0.73, 0.12], 0.02)
    stand.add(cradle)
    const cradleLip = box(0.18, 0.06, 0.024, standMat, [0, 0.7, 0.165], 0.01)
    stand.add(cradleLip)
    const rubber = box(0.17, 0.012, 0.07, new THREE.MeshStandardMaterial({ color: 0x151618, roughness: 0.85 }), [0, 0.7, 0.12], 0.008)
    stand.add(rubber)
    stand.position.set(1.4, 0, 0.2)
    stand.rotation.y = -0.35
    this.props.add(stand)
    this.phoneStand = stand
    this.phoneStandAnchor = new THREE.Vector3(1.4, 0.77, 0.16)
    const ss = contactShadow(0.55, 0.4)
    ss.position.set(1.4, 0.001, 0.2)
    this.props.add(ss)

    const plant = new THREE.Group()
    const potMat = new THREE.MeshPhysicalMaterial({ color: 0x2b2b2c, roughness: 0.4, metalness: 0.1, clearcoat: 0.5 })
    const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.12, 0.26, 40), potMat)
    pot.position.y = 0.13
    pot.castShadow = true
    plant.add(pot)
    const soil = new THREE.Mesh(new THREE.CircleGeometry(0.145, 32), new THREE.MeshStandardMaterial({ color: 0x16110c, roughness: 1 }))
    soil.rotation.x = -Math.PI / 2
    soil.position.y = 0.262
    plant.add(soil)
    const leafMat = new THREE.MeshPhysicalMaterial({ color: 0x2e4b3a, roughness: 0.62, side: THREE.DoubleSide, clearcoat: 0.25 })
    for (let i = 0; i < 9; i++) {
      const leaf = new THREE.Mesh(new THREE.SphereGeometry(0.07, 12, 8), leafMat)
      const a = i / 9 * Math.PI * 2
      const r = 0.1 + Math.random() * 0.08
      leaf.scale.set(0.55, 1.8, 0.25)
      leaf.position.set(Math.cos(a) * r, 0.36 + Math.random() * 0.2, Math.sin(a) * r)
      leaf.rotation.z = Math.cos(a) * 0.6
      leaf.rotation.x = Math.sin(a) * 0.4
      leaf.castShadow = true
      plant.add(leaf)
    }
    plant.position.set(-1.72, 0, -0.55)
    this.props.add(plant)

    const diffuser = new THREE.Group()
    const diffMat = new THREE.MeshPhysicalMaterial({ color: 0x272727, roughness: 0.28, metalness: 0.6, clearcoat: 0.8 })
    const db = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.15, 0.22, 40), diffMat)
    db.position.y = 0.11
    db.castShadow = true
    diffuser.add(db)
    const dc = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.04, 0.14, 20), new THREE.MeshStandardMaterial({ color: 0x8a7d68, roughness: 0.7 }))
    dc.position.y = 0.28
    diffuser.add(dc)
    diffuser.position.set(1.86, 0, -0.48)
    this.props.add(diffuser)

    const trayMat = new THREE.MeshPhysicalMaterial({ color: 0x8a765d, metalness: 1, roughness: 0.3 })
    const tray = new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.17, 0.025, 48), trayMat)
    tray.position.set(0.92, 0.012, 1.18)
    tray.castShadow = true
    this.props.add(tray)
    const trayInner = new THREE.Mesh(new THREE.CircleGeometry(0.15, 40), new THREE.MeshStandardMaterial({ color: 0x3a3025, roughness: 0.6 }))
    trayInner.rotation.x = -Math.PI / 2
    trayInner.position.set(0.92, 0.026, 1.18)
    this.props.add(trayInner)
    const key = box(0.035, 0.008, 0.14, trayMat, [0.92, 0.035, 1.18], 0.005)
    key.rotation.y = 0.5
    this.props.add(key)

    const boxShadow = contactShadow(2.05, 0.55)
    boxShadow.position.set(0, 0.001, 0)
    boxShadow.scale.set(0.55, 1, 1)
    this.props.add(boxShadow)
    this.boxShadow = boxShadow

    const penMat = new THREE.MeshPhysicalMaterial({ color: 0x15161a, metalness: 0.6, roughness: 0.25 })
    const pen = new THREE.Mesh(new THREE.CylinderGeometry(0.009, 0.011, 0.42, 16), penMat)
    pen.rotation.z = Math.PI / 2
    pen.rotation.y = 0.3
    pen.position.set(-1.3, 0.012, 1.05)
    pen.castShadow = true
    this.props.add(pen)
  }

  makePropLogo(text) {
    const canvas = document.createElement('canvas')
    canvas.width = 256
    canvas.height = 64
    const ctx = canvas.getContext('2d')
    ctx.clearRect(0, 0, 256, 64)
    ctx.fillStyle = 'rgba(35,38,40,.65)'
    ctx.font = '600 22px Helvetica, Arial, sans-serif'
    ctx.textAlign = 'center'
    ctx.letterSpacing = '8px'
    ctx.fillText(text, 128, 39)
    const tex = new THREE.CanvasTexture(canvas)
    tex.colorSpace = THREE.SRGBColorSpace
    return tex
  }

  createBox() {
    this.box = new PhoneBox()
    this.scene.add(this.box.group)
    this.box.group.position.set(0, 0, 0)
  }

  createLights() {
    RectAreaLightUniformsLib.init()
    this.hemi = new THREE.HemisphereLight(0xbfd0e0, 0x2a1d14, 0.4)
    this.scene.add(this.hemi)
    this.key = new THREE.DirectionalLight(0xfff1dd, 3.3)
    this.key.position.set(-2.8, 4.6, 2.4)
    this.key.target.position.set(0, 0.1, 0)
    this.key.castShadow = true
    this.key.shadow.mapSize.set(2048, 2048)
    this.key.shadow.camera.left = -3.2
    this.key.shadow.camera.right = 3.2
    this.key.shadow.camera.top = 3.2
    this.key.shadow.camera.bottom = -3.2
    this.key.shadow.camera.near = 0.5
    this.key.shadow.camera.far = 9
    this.key.shadow.bias = -0.0002
    this.key.shadow.normalBias = 0.018
    this.key.shadow.radius = 4
    this.scene.add(this.key, this.key.target)

    this.fill = new THREE.DirectionalLight(0xb7ccdb, 0.75)
    this.fill.position.set(3.5, 2.2, 2.6)
    this.fill.target.position.set(0, 0.2, 0)
    this.scene.add(this.fill, this.fill.target)

    this.rim = new THREE.SpotLight(0xffd7a3, 38, 8, 0.55, 0.85, 1.4)
    this.rim.position.set(2.6, 3.2, -1.8)
    this.rim.target.position.set(0.1, 0.25, 0)
    this.rim.castShadow = true
    this.rim.shadow.mapSize.set(1024, 1024)
    this.rim.shadow.bias = -0.0003
    this.rim.shadow.normalBias = 0.02
    this.scene.add(this.rim, this.rim.target)

    this.softbox = new THREE.RectAreaLight(0xffe6c7, 8.0, 2.4, 1.4)
    this.softbox.position.set(-0.2, 3.0, 1.0)
    this.softbox.lookAt(0, 0, 0)
    this.scene.add(this.softbox)

    this.softbox2 = new THREE.RectAreaLight(0xc6d9e8, 3.0, 1.6, 1.0)
    this.softbox2.position.set(2.4, 2.0, 1.8)
    this.softbox2.lookAt(0, 0.2, 0)
    this.scene.add(this.softbox2)

    this.tableSpot = new THREE.SpotLight(0xffeeda, 30, 6, 0.75, 1, 1.2)
    this.tableSpot.position.set(0, 3.1, 0.7)
    this.tableSpot.target.position.set(0, 0, 0.2)
    this.scene.add(this.tableSpot, this.tableSpot.target)
  }

  createParticles() {
    const count = 380
    const positions = new Float32Array(count * 3)
    const sizes = new Float32Array(count)
    this.dustData = []
    for (let i = 0; i < count; i++) {
      const x = (Math.random() - 0.5) * 5
      const y = Math.random() * 2.6 + 0.1
      const z = (Math.random() - 0.5) * 4
      positions[i * 3] = x
      positions[i * 3 + 1] = y
      positions[i * 3 + 2] = z
      sizes[i] = Math.random()
      this.dustData.push({ baseY: y, speed: 0.01 + Math.random() * 0.04, phase: Math.random() * Math.PI * 2 })
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1))
    const mat = new THREE.PointsMaterial({
      color: 0xffe9c9, size: 0.008, transparent: true, opacity: 0.28,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true
    })
    this.dust = new THREE.Points(geo, mat)
    this.dust.frustumCulled = false
    this.scene.add(this.dust)

    const sparkCount = 70
    const sparkPos = new Float32Array(sparkCount * 3)
    for (let i = 0; i < sparkCount; i++) {
      sparkPos[i * 3] = (Math.random() - 0.5) * 1.4
      sparkPos[i * 3 + 1] = 0.4 + Math.random() * 1.6
      sparkPos[i * 3 + 2] = (Math.random() - 0.5) * 0.8
    }
    const sparkGeo = new THREE.BufferGeometry()
    sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPos, 3))
    this.sparkMat = new THREE.PointsMaterial({
      color: 0xffdca8, size: 0.018, transparent: true, opacity: 0,
      blending: THREE.AdditiveBlending, depthWrite: false
    })
    this.sparkles = new THREE.Points(sparkGeo, this.sparkMat)
    this.sparkles.frustumCulled = false
    this.scene.add(this.sparkles)
  }

  createReveal() {
    this.revealLight = new THREE.SpotLight(0xffe0b3, 0, 7, 0.5, 1, 1.4)
    this.revealLight.position.set(0, 3.2, 1.6)
    this.revealLight.target.position.set(0, 0.5, 0)
    this.scene.add(this.revealLight, this.revealLight.target)

    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xd8b98c, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide, depthWrite: false
    })
    this.revealRing = new THREE.Mesh(new THREE.RingGeometry(0.44, 0.46, 80), ringMat)
    this.revealRing.rotation.x = -Math.PI / 2
    this.revealRing.position.set(0, 0.08, 0)
    this.scene.add(this.revealRing)

    const glow = makeGradientSprite('rgba(255,222,170,.75)', 'rgba(199,150,84,.2)', 128)
    this.revealGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glow, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
    }))
    this.revealGlow.scale.set(2.2, 2.2, 1)
    this.revealGlow.position.set(0, 0.8, 0)
    this.scene.add(this.revealGlow)
  }

  setReveal(amount) {
    this.revealLight.intensity = amount * 42
    this.revealRing.material.opacity = amount * 0.7
    this.revealRing.scale.setScalar(1 + amount * 0.25)
    this.revealGlow.material.opacity = amount * 0.28
    this.sparkMat.opacity = amount * 0.9
  }

  setNight(night) {
    this.night = night
    this.key.intensity = night ? 0.35 : 3.3
    this.key.color.set(night ? '#9bb5d1' : '#fff1dd')
    this.hemi.intensity = night ? 0.12 : 0.4
    this.hemi.color.set(night ? '#445d7a' : '#bfd0e0')
    this.fill.intensity = night ? 0.28 : 0.75
    this.rim.intensity = night ? 52 : 38
    this.rim.color.set(night ? '#ffbf7a' : '#ffd7a3')
    this.softbox.intensity = night ? 2.4 : 8
    this.softbox2.intensity = night ? 0.8 : 3
    this.tableSpot.intensity = night ? 18 : 30
    this.softbox.color.set(night ? '#ffc58c' : '#ffe6c7')
    this.room.traverse(o => {
      if (o.material === this.wallMaterial) {
        this.wallMaterial.color.set(night ? '#181a20' : '#2c2b2b')
      }
    })
    this.ledMaterial.color.set(night ? '#ffcf8a' : '#d9b27a')
    this.windowMaterial.color.set(night ? '#1a2b46' : '#aec4cc')
    this.windowMaterial.opacity = night ? 0.1 : 0.16
    this.scene.fog.color.set(night ? '#050609' : '#08090b')
    this.scene.environmentIntensity = night ? 0.34 : 0.75
    this.dust.material.opacity = night ? 0.38 : 0.28
    this.dust.material.color.set(night ? '#ffd7a0' : '#ffe9c9')
  }

  setTableTone(tone) {
    const wood = this.woodTextures[tone] || this.woodTextures.walnut
    this.tableMaterial.map = wood.map
    this.tableMaterial.roughnessMap = wood.roughnessMap
    this.tableMaterial.bumpMap = wood.bumpMap
    this.tableMaterial.needsUpdate = true
  }

  setBackdrop(color) {
    this.wallMaterial.color.set(color)
  }

  updateCamera(aspect) {
    this.camera.aspect = aspect
    this.camera.updateProjectionMatrix()
  }

  update(dt, elapsed) {
    this.clockTime += dt
    const pos = this.dust.geometry.attributes.position
    for (let i = 0; i < this.dustData.length; i++) {
      const d = this.dustData[i]
      pos.array[i * 3 + 1] += d.speed * dt
      pos.array[i * 3] += Math.sin(elapsed * 0.35 + d.phase) * dt * 0.006
      if (pos.array[i * 3 + 1] > 2.8) pos.array[i * 3 + 1] = 0.08
    }
    pos.needsUpdate = true
    if (this.sparkMat.opacity > 0.01) {
      const sp = this.sparkles.geometry.attributes.position
      for (let i = 0; i < sp.count; i++) {
        sp.array[i * 3 + 1] += dt * (0.025 + (i % 5) * 0.01)
        sp.array[i * 3] += Math.sin(elapsed * 0.7 + i) * dt * 0.008
        if (sp.array[i * 3 + 1] > 2.1) sp.array[i * 3 + 1] = 0.25
      }
      sp.needsUpdate = true
    }
    this.revealRing.rotation.z += dt * 0.12
    this.softbox.intensity += Math.sin(elapsed * 0.4) * 0.0015
  }
}

:root {
  --bg: #08090b;
  --ink: #f3efe6;
  --muted: rgba(243, 239, 230, 0.55);
  --faint: rgba(243, 239, 230, 0.28);
  --gold: #d6b98c;
  --gold-bright: #f1dab4;
  --gold-deep: #a67f4e;
  --line: rgba(255, 255, 255, 0.11);
  --glass: rgba(16, 18, 22, 0.72);
  --glass-2: rgba(22, 24, 29, 0.88);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --font: 'Manrope', 'Helvetica Neue', Arial, sans-serif;
  --serif: 'Cormorant Garamond', Georgia, serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}
body { touch-action: none; }
button, input { font: inherit; }
button { color: inherit; }
button:focus-visible, input:focus-visible { outline: 1px solid var(--gold); outline-offset: 3px; }
#app { position: fixed; inset: 0; overflow: hidden; background: #08090b; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

.ambient-vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 34%, rgba(0, 0, 0, 0.24) 76%, rgba(0, 0, 0, 0.62) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.3), transparent 18%, transparent 70%, rgba(0, 0, 0, 0.48));
}
.ambient-grain {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0.17; mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
}

/* ============ LOADING ============ */
.loading {
  position: fixed; inset: 0; z-index: 90; display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: radial-gradient(circle at 50% 40%, #17181d 0%, #08090b 60%);
  transition: opacity 0.9s ease, visibility 0.9s;
}
.loading.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.loader-aura {
  font-size: 12px; letter-spacing: 0.8em; color: var(--gold); margin-bottom: 28px;
  animation: pulseText 2.4s ease-in-out infinite;
}
.loader-title { font-weight: 200; font-size: clamp(22px, 3.2vw, 38px); letter-spacing: 0.24em; }
.loader-title em { font-family: var(--serif); font-weight: 400; color: var(--gold); font-style: italic; letter-spacing: 0.06em; }
.loader-line { width: min(300px, 60vw); height: 1px; background: rgba(255, 255, 255, 0.12); margin-top: 32px; overflow: hidden; }
.loader-line span { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, #8f6c44, #f0ddb9); transition: width 0.45s ease; }
.loader-copy { margin-top: 18px; font-size: 10px; letter-spacing: 0.28em; color: var(--faint); text-transform: uppercase; }

/* ============ SPLASH ============ */
.splash {
  position: fixed; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(13, 15, 19, 0.28) 0%, rgba(7, 8, 10, 0.75) 55%, rgba(5, 6, 8, 0.95) 100%),
    linear-gradient(180deg, rgba(6, 7, 9, 0.55), rgba(6, 7, 9, 0.2) 35%, rgba(6, 7, 9, 0.9));
  backdrop-filter: blur(2px);
  transition: opacity 1.1s ease, visibility 1.1s;
}
body.started .splash { opacity: 0; visibility: hidden; pointer-events: none; }
.splash-content { position: relative; z-index: 2; text-align: center; padding: 20px; max-width: 1100px; }
.splash-eyebrow {
  display: flex; align-items: center; justify-content: center; gap: 14px;
  font-size: 9.5px; letter-spacing: 0.32em; color: rgba(243, 239, 230, 0.55); text-transform: uppercase;
  animation: fadeUp 1s 0.2s both;
}
.splash-eyebrow span { width: 34px; height: 1px; background: var(--gold); }
.splash-title { margin: 24px 0 18px; line-height: 0.88; font-weight: 200; letter-spacing: 0.035em; }
.title-line { display: block; }
.line-1 { font-size: clamp(56px, 8.6vw, 138px); letter-spacing: 0.13em; animation: titleIn 1.2s 0.35s both cubic-bezier(0.2, 0.7, 0.2, 1); }
.line-2 { font-family: var(--serif); font-weight: 300; font-size: clamp(60px, 9.4vw, 152px); letter-spacing: 0.01em; animation: titleIn 1.2s 0.5s both cubic-bezier(0.2, 0.7, 0.2, 1); }
.line-2 em {
  font-style: italic; font-weight: 400;
  background: linear-gradient(135deg, #f8e8c9, #c7a16e 50%, #8f6a3d);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.splash-sub {
  color: rgba(243, 239, 230, 0.58); font-size: clamp(12px, 1.1vw, 15px); line-height: 1.9; font-weight: 300;
  letter-spacing: 0.03em; margin: 22px auto 38px; animation: fadeUp 1s 0.7s both;
}
.splash-actions { display: flex; gap: 14px; justify-content: center; align-items: center; animation: fadeUp 1s 0.85s both; }
.splash-meta {
  display: flex; align-items: center; justify-content: center; gap: 26px; margin-top: 48px;
  animation: fadeUp 1s 1s both;
}
.splash-meta div { display: flex; flex-direction: column; gap: 4px; }
.splash-meta strong { font-size: 18px; font-weight: 300; color: var(--gold-bright); letter-spacing: 0.08em; }
.splash-meta span { font-size: 8.5px; letter-spacing: 0.22em; color: var(--faint); text-transform: uppercase; }
.splash-meta i { width: 1px; height: 24px; background: var(--line); }
.splash-footer {
  position: absolute; bottom: 24px; left: 32px; right: 32px; display: flex; justify-content: space-between;
  font-size: 8px; letter-spacing: 0.24em; color: rgba(243, 239, 230, 0.28); text-transform: uppercase;
}
.splash-orbit {
  position: absolute; border: 1px solid rgba(214, 185, 140, 0.08); border-radius: 50%; pointer-events: none;
}
.orbit-a { width: 74vw; height: 74vw; max-width: 980px; max-height: 980px; animation: spin 50s linear infinite; }
.orbit-b { width: 48vw; height: 48vw; max-width: 620px; max-height: 620px; border-style: dashed; animation: spin 35s linear infinite reverse; }
.orbit-a::before, .orbit-b::before {
  content: ''; position: absolute; top: 50%; left: -3px; width: 5px; height: 5px; border-radius: 50%;
  background: var(--gold); box-shadow: 0 0 18px 4px rgba(214, 185, 140, 0.4);
}

/* ============ BUTTONS ============ */
.btn {
  position: relative; border: 0; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  height: 48px; padding: 0 28px; border-radius: 100px; font-size: 10px; font-weight: 600; letter-spacing: 0.18em;
  text-transform: uppercase; transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease, opacity 0.25s;
  white-space: nowrap; -webkit-tap-highlight-color: transparent;
}
.btn:hover { transform: translateY(-2px); }
.btn:active { transform: translateY(0) scale(0.985); }
.btn:disabled { opacity: 0.35; pointer-events: none; }
.btn svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.btn-gold {
  color: #16120d;
  background: linear-gradient(135deg, #f4e2c4 0%, #d8b98a 46%, #b48b58 100%);
  box-shadow: 0 10px 34px rgba(197, 160, 106, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
.btn-gold:hover { box-shadow: 0 16px 44px rgba(197, 160, 106, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.5); }
.btn-ghost {
  color: rgba(243, 239, 230, 0.78); background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 255, 255, 0.13); backdrop-filter: blur(12px);
}
.btn-ghost:hover { background: rgba(255, 255, 255, 0.08); border-color: rgba(255, 255, 255, 0.24); }
.btn-hero { height: 56px; padding: 0 34px; font-size: 10.5px; }
.btn.full { width: 100%; margin-top: 4px; }

.icon-btn {
  width: 38px; height: 38px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(255, 255, 255, 0.035); cursor: pointer; display: inline-flex; align-items: center; justify-content: center;
  transition: all 0.25s ease; backdrop-filter: blur(10px); padding: 0;
}
.icon-btn:hover { background: rgba(255, 255, 255, 0.09); border-color: rgba(214, 185, 140, 0.35); }
.icon-btn svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn.muted { color: rgba(255, 255, 255, 0.28); }
.quality-btn span { font-size: 7px; letter-spacing: 0.12em; color: var(--gold); }

/* ============ CHROME ============ */
.chrome { position: fixed; z-index: 12; transition: opacity 0.7s ease, transform 0.7s ease; }
body:not(.started) .chrome { opacity: 0; pointer-events: none; }
.topbar {
  top: 0; left: 0; right: 0; height: 76px; display: flex; align-items: center; justify-content: space-between;
  padding: 0 26px; background: linear-gradient(180deg, rgba(6, 7, 9, 0.7), transparent); pointer-events: none;
}
.topbar > * { pointer-events: auto; }
.brand { display: flex; align-items: center; gap: 12px; min-width: 210px; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center;
  border: 1px solid rgba(214, 185, 140, 0.5); color: var(--gold-bright); font-family: var(--serif);
  font-size: 19px; font-style: italic; background: rgba(214, 185, 140, 0.05);
}
.brand-text { display: flex; flex-direction: column; gap: 3px; }
.brand-text strong { font-size: 12px; font-weight: 600; letter-spacing: 0.38em; }
.brand-text span { font-size: 7.5px; letter-spacing: 0.2em; color: var(--faint); }
.steps { display: flex; align-items: center; gap: 4px; }
.step {
  display: flex; align-items: center; gap: 7px; padding: 7px 10px; border-radius: 30px;
  border: 1px solid transparent; transition: all 0.35s ease; opacity: 0.42;
}
.step i { font-style: normal; font-size: 7px; color: var(--faint); }
.step span { font-size: 7.5px; letter-spacing: 0.14em; }
.step.active { opacity: 1; border-color: rgba(214, 185, 140, 0.28); background: rgba(214, 185, 140, 0.07); }
.step.active i { color: var(--gold); }
.step.done { opacity: 0.7; }
.step.done i { color: var(--gold); }
.top-actions { display: flex; align-items: center; gap: 7px; min-width: 210px; justify-content: flex-end; }

/* ============ MODE RAIL ============ */
.mode-rail {
  left: 20px; top: 96px; width: 96px; padding: 8px; display: flex; flex-direction: column; gap: 3px;
  background: rgba(14, 16, 20, 0.52); border: 1px solid rgba(255, 255, 255, 0.07); border-radius: 18px;
  backdrop-filter: blur(20px); box-shadow: 0 18px 50px rgba(0, 0, 0, 0.3);
}
.mode-btn {
  position: relative; border: 0; background: transparent; cursor: pointer; padding: 10px 8px 9px; border-radius: 12px;
  display: flex; flex-direction: column; align-items: flex-start; gap: 3px; text-align: left; transition: all 0.3s ease;
  -webkit-tap-highlight-color: transparent;
}
.mode-btn:hover { background: rgba(255, 255, 255, 0.05); }
.mode-btn.active { background: linear-gradient(135deg, rgba(214, 185, 140, 0.16), rgba(214, 185, 140, 0.04)); }
.mode-btn.active::before { content: ''; position: absolute; left: 0; top: 14px; bottom: 14px; width: 2px; border-radius: 2px; background: var(--gold); }
.mode-num { font-size: 6.5px; letter-spacing: 0.1em; color: var(--faint); }
.mode-label { font-size: 8px; letter-spacing: 0.08em; font-weight: 600; }
.mode-btn small { font-size: 8px; color: rgba(243, 239, 230, 0.36); font-weight: 400; }
.mode-btn.active .mode-num, .mode-btn.active .mode-label { color: var(--gold-bright); }
.mode-btn.active small { color: rgba(243, 239, 230, 0.55); }

/* ============ GUIDE ============ */
.glass {
  background: linear-gradient(145deg, rgba(20, 22, 27, 0.82), rgba(11, 13, 17, 0.72));
  border: 1px solid rgba(255, 255, 255, 0.09); box-shadow: var(--shadow); backdrop-filter: blur(26px) saturate(1.1);
}
.guide-card {
  left: 136px; bottom: 104px; width: 350px; padding: 22px 22px 18px; border-radius: 20px;
  transition: opacity 0.4s, transform 0.4s;
}
.guide-top { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.guide-kicker { font-size: 7.5px; letter-spacing: 0.18em; color: var(--faint); text-transform: uppercase; }
.guide-kicker span { color: var(--gold); }
.guide-timer { font-size: 6.5px; letter-spacing: 0.15em; color: rgba(214, 185, 140, 0.7); border: 1px solid rgba(214, 185, 140, 0.25); padding: 4px 7px; border-radius: 20px; }
.guide-card h2 { margin: 16px 0 8px; font-size: 26px; font-weight: 300; letter-spacing: -0.02em; line-height: 1.15; }
.guide-card p { margin: 0; font-size: 11px; line-height: 1.75; color: var(--muted); font-weight: 300; }
.guide-hint {
  display: flex; align-items: center; gap: 8px; margin: 16px 0 14px; padding: 10px 12px;
  border-radius: 10px; background: rgba(214, 185, 140, 0.07); border: 1px dashed rgba(214, 185, 140, 0.28);
  color: var(--gold-bright); font-size: 8px; letter-spacing: 0.14em; transition: all 0.35s;
}
.guide-hint svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.4; animation: hintUp 1.8s ease-in-out infinite; }
.guide-hint.done { border-style: solid; border-color: rgba(126, 176, 142, 0.35); background: rgba(126, 176, 142, 0.08); color: #b8d6bd; }
.guide-hint.done svg { animation: none; }
.guide-action { width: 100%; height: 44px; font-size: 9px; }
.guide-progress { height: 2px; background: rgba(255, 255, 255, 0.08); margin-top: 14px; border-radius: 2px; overflow: hidden; }
.guide-progress span { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, #8f6c44, #f0ddb9); transition: width 0.4s ease; }
body.info-open .guide-card { opacity: 0; transform: translateY(8px); pointer-events: none; }

/* ============ INFO PANEL ============ */
.info-panel {
  right: 24px; top: 98px; width: 320px; padding: 26px 24px 22px; border-radius: 20px;
  opacity: 0; visibility: hidden; transform: translateX(16px); transition: all 0.4s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.info-panel.visible { opacity: 1; visibility: visible; transform: translateX(0); }
.panel-close {
  position: absolute; top: 12px; right: 12px; width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.04); color: var(--muted); cursor: pointer; font-size: 18px; line-height: 1;
}
.info-icon {
  width: 52px; height: 52px; border-radius: 15px; display: grid; place-items: center;
  background: linear-gradient(145deg, rgba(214, 185, 140, 0.2), rgba(214, 185, 140, 0.04));
  border: 1px solid rgba(214, 185, 140, 0.25); color: var(--gold-bright); font-size: 24px; margin-bottom: 18px;
}
.info-kicker { font-size: 7.5px; letter-spacing: 0.24em; color: var(--gold); }
.info-panel h3 { margin: 10px 0 10px; font-size: 23px; font-weight: 300; line-height: 1.2; }
.info-panel p { margin: 0; color: var(--muted); font-size: 11.5px; line-height: 1.75; font-weight: 300; }
.info-specs { margin: 18px 0; border-top: 1px solid var(--line); }
.info-specs div { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.055); font-size: 9.5px; }
.info-specs span:first-child { color: var(--faint); letter-spacing: 0.1em; font-size: 7.5px; text-transform: uppercase; }
.info-specs span:last-child { color: rgba(243, 239, 230, 0.78); text-align: right; }
.info-actions { display: flex; gap: 8px; margin-top: 18px; }
.info-actions .btn { flex: 1; height: 40px; font-size: 8px; padding: 0 12px; }

/* ============ BOTTOM DOCK ============ */
.bottom-bar {
  left: 50%; bottom: 24px; transform: translateX(-50%); display: flex; align-items: center; gap: 5px;
  padding: 7px; border-radius: 100px; background: rgba(13, 15, 19, 0.7); border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(24px); box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
}
.dock-btn {
  border: 0; background: transparent; color: var(--muted); cursor: pointer; height: 38px; padding: 0 16px; border-radius: 100px;
  display: flex; align-items: center; gap: 8px; font-size: 8px; letter-spacing: 0.14em; transition: all 0.25s; white-space: nowrap;
}
.dock-btn:hover { background: rgba(255, 255, 255, 0.07); color: var(--ink); }
.dock-btn svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
.dock-btn b { min-width: 17px; height: 17px; border-radius: 50%; display: grid; place-items: center; background: var(--gold); color: #17120c; font-size: 8px; }
.dock-next { background: linear-gradient(135deg, rgba(214, 185, 140, 0.95), rgba(177, 138, 86, 0.95)); color: #17120c; font-weight: 700; }
.dock-next:hover { background: linear-gradient(135deg, #f0ddb9, #c39a65); color: #17120c; }
.dock-next:disabled { opacity: 0.3; pointer-events: none; }
.dock-sep { width: 1px; height: 18px; background: var(--line); }

/* ============ HOLD POWER ============ */
.hold-power {
  position: fixed; z-index: 18; left: 50%; bottom: 96px; transform: translate(-50%, 18px);
  display: flex; align-items: center; gap: 14px; padding: 12px 22px 12px 12px; border-radius: 100px;
  background: rgba(13, 15, 19, 0.8); border: 1px solid rgba(214, 185, 140, 0.3); backdrop-filter: blur(20px);
  opacity: 0; visibility: hidden; transition: all 0.4s ease; cursor: pointer; user-select: none;
}
.hold-power.visible { opacity: 1; visibility: visible; transform: translate(-50%, 0); }
.hold-power:active { transform: translate(-50%, 0) scale(0.98); }
.hold-ring { width: 48px; height: 48px; position: relative; display: grid; place-items: center; }
.hold-ring svg { position: absolute; inset: 0; transform: rotate(-90deg); }
.hold-ring circle { fill: none; stroke-width: 3; }
.hold-ring .ring-bg { stroke: rgba(255, 255, 255, 0.12); }
.hold-ring .ring-fg { stroke: var(--gold-bright); stroke-dasharray: 276; stroke-dashoffset: 276; stroke-linecap: round; transition: stroke-dashoffset 0.08s linear; }
.hold-ring span { font-size: 17px; color: var(--gold-bright); }
.hold-copy { display: flex; flex-direction: column; gap: 4px; text-align: left; }
.hold-copy strong { font-size: 9px; letter-spacing: 0.16em; color: var(--gold-bright); }
.hold-copy small { font-size: 8.5px; color: var(--faint); letter-spacing: 0.04em; }

/* ============ TOAST / FLASH ============ */
.toast {
  position: fixed; z-index: 70; left: 50%; bottom: 88px; transform: translate(-50%, 20px); pointer-events: none;
  background: rgba(18, 20, 24, 0.94); border: 1px solid rgba(214, 185, 140, 0.25); color: var(--ink);
  padding: 11px 20px; border-radius: 100px; font-size: 10px; letter-spacing: 0.06em; opacity: 0;
  transition: all 0.35s cubic-bezier(0.2, 0.7, 0.2, 1); box-shadow: 0 14px 40px rgba(0, 0, 0, 0.4);
  max-width: min(90vw, 460px); text-align: center;
}
.toast.visible { opacity: 1; transform: translate(-50%, 0); }
.flash { position: fixed; inset: 0; z-index: 80; background: #fff; opacity: 0; pointer-events: none; }
.flash.fire { animation: flash 0.55s ease-out; }

/* ============ CAMERA HUD ============ */
.camera-hud {
  position: fixed; inset: 0; z-index: 22; display: none; flex-direction: column; justify-content: space-between;
  pointer-events: none; padding: 22px 26px 24px;
}
body.camera-mode .camera-hud { display: flex; }
body.camera-mode .chrome { opacity: 0; pointer-events: none; }
body.camera-mode .guide-card, body.camera-mode .info-panel { opacity: 0; pointer-events: none; }
.camera-top { display: flex; align-items: center; gap: 22px; }
.camera-badge { display: flex; align-items: center; gap: 9px; font-size: 9px; letter-spacing: 0.24em; color: var(--gold-bright); }
.camera-badge i { width: 7px; height: 7px; border-radius: 50%; background: #d56b62; box-shadow: 0 0 12px #d56b62; animation: blink 1.6s infinite; }
.camera-meta { font-size: 8px; letter-spacing: 0.15em; color: var(--faint); }
.camera-meta span { color: var(--ink); }
.camera-exit { pointer-events: auto; margin-left: auto; border: 1px solid var(--line); background: rgba(12, 14, 18, 0.55); padding: 9px 16px; border-radius: 100px; font-size: 8px; letter-spacing: 0.15em; cursor: pointer; backdrop-filter: blur(14px); }
.viewfinder { position: absolute; inset: 9% 18%; pointer-events: none; }
.corner { position: absolute; width: 32px; height: 32px; border-color: rgba(255, 255, 255, 0.62); border-style: solid; }
.corner.tl { left: 0; top: 0; border-width: 1px 0 0 1px; }
.corner.tr { right: 0; top: 0; border-width: 1px 1px 0 0; }
.corner.bl { left: 0; bottom: 0; border-width: 0 0 1px 1px; }
.corner.br { right: 0; bottom: 0; border-width: 0 1px 1px 0; }
.vf-center { position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; transform: translate(-50%, -50%); border: 1px solid rgba(255, 255, 255, 0.32); border-radius: 50%; }
.vf-center::before, .vf-center::after { content: ''; position: absolute; background: rgba(255, 255, 255, 0.45); }
.vf-center::before { left: 50%; top: -7px; width: 1px; height: 60px; }
.vf-center::after { top: 50%; left: -7px; height: 1px; width: 60px; }
.vf-info { position: absolute; left: 0; bottom: -28px; right: 0; display: flex; justify-content: space-between; font-size: 7.5px; letter-spacing: 0.14em; color: rgba(255, 255, 255, 0.4); }
.camera-bottom { pointer-events: auto; display: flex; flex-direction: column; align-items: center; gap: 15px; }
.filter-row { display: flex; gap: 6px; padding: 5px; border-radius: 100px; background: rgba(12, 14, 18, 0.55); border: 1px solid var(--line); backdrop-filter: blur(16px); }
.filter-chip { border: 0; background: transparent; color: rgba(243, 239, 230, 0.4); font-size: 7.5px; letter-spacing: 0.13em; padding: 8px 14px; border-radius: 100px; cursor: pointer; }
.filter-chip.active { background: rgba(214, 185, 140, 0.16); color: var(--gold-bright); }
.shutter-row { display: flex; align-items: center; gap: 34px; }
.shutter-btn { width: 74px; height: 74px; border-radius: 50%; border: 2px solid rgba(255, 255, 255, 0.8); background: transparent; cursor: pointer; padding: 5px; }
.shutter-btn span { display: block; width: 100%; height: 100%; border-radius: 50%; background: #fff; transition: transform 0.15s; }
.shutter-btn:active span { transform: scale(0.9); }
.camera-mini { border: 0; background: transparent; color: var(--faint); font-size: 8px; letter-spacing: 0.16em; cursor: pointer; }
.gallery-strip { display: flex; gap: 6px; min-width: 90px; justify-content: flex-end; }
.gallery-strip img { width: 38px; height: 54px; object-fit: cover; border-radius: 6px; border: 1px solid rgba(255, 255, 255, 0.2); }
.zoom-row { display: flex; align-items: center; gap: 12px; font-size: 8px; color: var(--faint); letter-spacing: 0.1em; }
.zoom-row input { width: 200px; accent-color: #d6b98c; }

/* ============ MODALS ============ */
.modal-root { position: fixed; inset: 0; z-index: 50; display: none; align-items: center; justify-content: center; padding: 24px; }
.modal-root.open { display: flex; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(4, 5, 7, 0.76); backdrop-filter: blur(16px); }
.modal {
  position: relative; z-index: 2; width: min(680px, 94vw); max-height: 86vh; overflow: auto; border-radius: 24px;
  background: linear-gradient(145deg, rgba(24, 26, 31, 0.97), rgba(10, 12, 16, 0.98));
  border: 1px solid rgba(255, 255, 255, 0.11); box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7);
  padding: 34px 34px 28px; animation: modalIn 0.4s cubic-bezier(0.2, 0.7, 0.2, 1);
  scrollbar-width: thin; scrollbar-color: rgba(214, 185, 140, 0.3) transparent;
}
.modal-wide { width: min(960px, 94vw); }
.modal-close {
  position: absolute; top: 16px; right: 16px; width: 34px; height: 34px; border-radius: 50%;
  border: 1px solid var(--line); background: rgba(255, 255, 255, 0.04); color: var(--muted); cursor: pointer; font-size: 20px;
}
.modal-head { padding-right: 40px; margin-bottom: 24px; }
.eyebrow { font-size: 8px; letter-spacing: 0.28em; color: var(--gold); }
.modal-head h2 { margin: 10px 0 8px; font-size: clamp(28px, 3.4vw, 40px); font-weight: 300; letter-spacing: -0.03em; }
.modal-head p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.7; font-weight: 300; max-width: 640px; }
.modal-note { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-top: 22px; padding-top: 18px; border-top: 1px solid var(--line); font-size: 9px; color: var(--faint); letter-spacing: 0.04em; }
.modal-note .btn { height: 38px; font-size: 8px; }
.inventory-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.inv-card {
  position: relative; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.03);
  border-radius: 14px; padding: 18px 14px 14px; cursor: pointer; transition: all 0.25s; text-align: left; overflow: hidden;
}
.inv-card:hover { border-color: rgba(214, 185, 140, 0.3); background: rgba(214, 185, 140, 0.06); transform: translateY(-2px); }
.inv-card.locked { opacity: 0.38; }
.inv-card .inv-icon { font-size: 26px; color: var(--gold-bright); margin-bottom: 24px; display: block; }
.inv-card strong { display: block; font-size: 10px; font-weight: 500; line-height: 1.4; }
.inv-card small { display: block; margin-top: 5px; font-size: 7.5px; letter-spacing: 0.1em; color: var(--faint); text-transform: uppercase; }
.inv-card .check { position: absolute; top: 10px; right: 10px; width: 18px; height: 18px; border-radius: 50%; background: rgba(126, 176, 142, 0.2); color: #a9d0b1; display: grid; place-items: center; font-size: 10px; }
.collection-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.collection-card {
  position: relative; border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 16px; padding: 18px; cursor: pointer;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.012)); transition: all 0.3s; overflow: hidden;
}
.collection-card:hover { border-color: rgba(214, 185, 140, 0.4); transform: translateY(-3px); }
.collection-card.selected { border-color: rgba(214, 185, 140, 0.6); background: linear-gradient(145deg, rgba(214, 185, 140, 0.13), rgba(214, 185, 140, 0.02)); }
.collection-card .cc-swatch {
  height: 120px; border-radius: 12px; margin-bottom: 16px; position: relative; overflow: hidden;
  background: radial-gradient(circle at 30% 20%, var(--c1), var(--c2) 60%, #08090b); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
}
.cc-swatch::after {
  content: ''; position: absolute; width: 52px; height: 94px; right: 20px; top: 13px; border-radius: 13px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.18), rgba(255, 255, 255, 0.03)); border: 1px solid rgba(255, 255, 255, 0.25);
  transform: rotate(8deg);
}
.cc-swatch::before {
  content: ''; position: absolute; width: 20px; height: 38px; right: 34px; top: 25px; border-radius: 6px;
  background: #101216; border: 1px solid rgba(214, 185, 140, 0.4); z-index: 2; transform: rotate(8deg);
}
.collection-card .cc-tier { font-size: 7px; letter-spacing: 0.16em; color: var(--gold); text-transform: uppercase; }
.collection-card h3 { margin: 7px 0 5px; font-size: 17px; font-weight: 400; letter-spacing: -0.01em; }
.collection-card p { margin: 0; font-size: 8px; color: var(--faint); letter-spacing: 0.06em; }
.collection-card .cc-price { margin-top: 14px; font-size: 10px; color: rgba(243, 239, 230, 0.7); }
.collection-card .cc-check { position: absolute; top: 12px; right: 12px; width: 22px; height: 22px; border-radius: 50%; background: var(--gold); color: #16120d; display: grid; place-items: center; font-size: 11px; }
.custom-layout { display: grid; grid-template-columns: 300px 1fr; gap: 34px; }
