.control-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.text-input { height: 42px; border-radius: 10px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.04); color: var(--ink); padding: 0 14px; font-size: 12px; letter-spacing: 0.06em; }
.swatches, .color-row { display: flex; gap: 8px; flex-wrap: wrap; }
.swatch { width: 36px; height: 36px; border-radius: 50%; border: 2px solid transparent; cursor: pointer; position: relative; }
.swatch.active { border-color: var(--gold-bright); box-shadow: 0 0 0 3px rgba(214, 185, 140, 0.15); }
