.segmented { display: flex; gap: 4px; padding: 4px; border-radius: 10px; background: rgba(255, 255, 255, 0.04); border: 1px solid var(--line); }
.segmented button { flex: 1; border: 0; background: transparent; color: var(--faint); padding: 8px 6px; border-radius: 7px; font-size: 7.5px; letter-spacing: 0.06em; cursor: pointer; white-space: nowrap; }
